Object.assign(en,{platforms:'Platforms & compatibility',platformHeading:'Choose your platform. Know what works.',platformIntro:'Translate visible dialogue from a game window. The game still runs on its device or emulator.',setupTitle:'Start with a working translation service',setupSummary:'No server connected. Test your connection before sharing a screen or uploading files.',setupButton:'Set up & check server',pcTitle:'PC games',pcDesc:'A game window on your computer',xboxDesc:'Remote Play or a capture source',psDesc:'Your console or a compatible emulator',retroTitle:'Other platforms',retroDesc:'A readable window or screenshot',captureOnly:'SCREEN TRANSLATION PATH',platformTranslate:'Open translation studio',universalBoundary:'Selecting a platform does not install an emulator or enable ISO launch. No commercial game has been tested inside this platform yet.',compatTitle:'Actual feature support',featureLabel:'Feature',demoColumn:'Original demo',realColumn:'Your commercial games',playFeature:'Run a game',worksNow:'Works now',externalRuntime:'External console or emulator required',translationFeature:'Translate the screen into Arabic',scripted:'Prewritten dialogue',ocrRequired:'OCR server + Arabic model + capturable image',npcFeature:'NPC control and live modifiers',notImplemented:'Not implemented for commercial games',rewindFeature:'Rewind',localRewind:'After 60 seconds of gameplay',coopFeature:'Fully synchronized co-op',positionsOnly:'Positions only, with a server',cropLabel:'Text recognition area',cropFull:'Entire screen',cropBottom:'Bottom area — game dialogue',cropTop:'Top area',cropCenter:'Center of screen',installGuide:'How do I start the server on my computer?',installOne:'Download and extract the GitHub bundle, and install Docker Desktop.',installTwo:'Run python start.py in the project folder; it creates a token and prepares translation.',installThree:'Copy the token printed in your terminal and use the local site opened by the launcher.',installNote:'To connect this hosted site, use an HTTPS server. For local use, open the local site served by the gateway.'});
const platformDetails={
 pc:{name:['ألعاب الكمبيوتر','PC games'],description:['شغّل لعبتك على الكمبيوتر، ثم شارك نافذتها لقراءة النص الإنجليزي. هذا الموقع يعرض نسخة الفيديو المترجمة ولا يتحكم في لعبتك الأصلية.','Run your game on your computer, then share its window to read English text. This site shows a translated video preview; it does not control the original game.'],steps:[['افتح اللعبة في نافذة يمكن للمتصفح التقاطها.','Open the game in a window your browser can capture.'],['جهّز خادم الترجمة وتأكد من جاهزية OCR ونموذج العربية.','Set up the server and verify that OCR and the Arabic model are ready.'],['اختر نافذة اللعبة وحدد منطقة الحوار. استخدم لقطة شاشة إذا تعذّر الالتقاط.','Choose the game window and dialogue area. Use a screenshot if capture fails.']]},
 xbox:{name:['إكس بوكس','Xbox'],description:['لأجهزة Xbox One وSeries، يمكنك فتح جلسة Remote Play الرسمية ثم تجربة مشاركة نافذتها. للأجيال الأخرى يلزم مصدر صورة مناسب من جهازك. إضافة مسار Xbox هنا ليست محاكياً ولا تشغّل ملفاته.','For Xbox One and Series consoles, open an official Remote Play session and try sharing its window. Other generations need a suitable image source from your device. This Xbox path is not an emulator and does not launch Xbox files.'],steps:[['شغّل اللعبة على جهازك وأعدّ Remote Play وفق متطلبات Xbox الرسمية.','Run the game on your console and set up Remote Play following Xbox’s requirements.'],['افتح البث الرسمي في نافذة أخرى على الكمبيوتر. لا تسجّل دخول Xbox داخل هذا الموقع.','Open the official stream in another window on your computer. Do not enter your Xbox login on this site.'],['اربط خادم الترجمة ثم اختر نافذة البث. الالتقاط قد لا يكون متاحاً لكل محتوى أو جهاز.','Connect the translation server and choose the stream window. Capture may not be available for every device or type of content.']],url:'https://www.xbox.com/en-US/consoles/remote-play',link:['إعداد Xbox Remote Play الرسمي ↗','Official Xbox Remote Play setup ↗']},
 ps:{name:['بلايستيشن','PlayStation'],description:['شغّل اللعبة على جهازك أو محاكي متوافق مثبت لديك، ثم قدّم نافذة أو لقطة شاشة للترجمة. قائمة المنصات لا تعني أن هذا الموقع يحاكي جميع أجيال PlayStation.','Run the game on your console or a compatible emulator you have installed, then provide a window or screenshot for translation. This platform list does not mean this site emulates every PlayStation generation.'],steps:[['تحقق من توافق اللعبة مع الجهاز أو المحاكي المستخدم.','Check game compatibility with your console or emulator.'],['بالنسبة إلى PS2، راجع حالة اللعبة وإصدارها في قائمة PCSX2 الرسمية.','For PS2, check the game and revision in PCSX2’s official compatibility list.'],['شارك الصورة المقروءة مع استوديو الترجمة؛ التحكم يبقى في مصدر اللعبة.','Share the readable image with Translation studio; controls remain in the game source.']],url:'https://pcsx2.net/compat/',link:['قائمة توافق PCSX2 الرسمية ↗','Official PCSX2 compatibility list ↗']},
 retro:{name:['منصات أخرى','Other platforms'],description:['الترجمة تعتمد على النص الظاهر بالصورة، وليس صيغة ملف اللعبة. يلزم أن تعمل اللعبة خارج الموقع وأن يسمح مصدر الصورة بالتقاطها.','Translation depends on visible text, not the game file format. The game must run outside this site and its image source must allow capture.'],steps:[['شغّل اللعبة على جهاز أو محاكي مناسب تملكه.','Run the game on a suitable device or emulator you own.'],['قدّم لقطة شاشة إنجليزية واضحة، أو نافذة قابلة للمشاركة.','Provide a legible English screenshot or a shareable window.'],['جرّب ترجمة الحوار وتحقق من الدقة؛ النصوص المزخرفة قد لا تُقرأ جيداً.','Test dialogue translation and check accuracy; stylized text may not be recognized well.']]}
};
let selectedPlatform='pc',healthState=null;
function renderPlatform(){const p=platformDetails[selectedPlatform],i=lang==='ar'?0:1;$('#platformName').textContent=p.name[i];$('#platformInstructions').textContent=p.description[i];$('#platformSteps').replaceChildren();for(const step of p.steps){const li=document.createElement('li');li.textContent=step[i];$('#platformSteps').append(li)}const link=$('#platformReference');link.hidden=!p.url;if(p.url){link.href=p.url;link.textContent=p.link[i]}refreshHealth();}
$$('[data-platform]').forEach(b=>b.onclick=()=>{selectedPlatform=b.dataset.platform;$$('[data-platform]').forEach(c=>{c.classList.toggle('selected',c===b);c.setAttribute('aria-pressed',String(c===b))});renderPlatform()});$$('[data-open]').forEach(b=>b.onclick=()=>view(b.dataset.open));$('#platformTranslate').onclick=()=>{view('translate');toast(t('المصدر المختار: ','Selected source: ')+platformDetails[selectedPlatform].name[lang==='ar'?0:1])};
function refreshHealth(){const area=$('#capabilityChecks');area.replaceChildren();if(!healthState){$('#serverStatus').textContent=t('الخادم غير مفحوص','Server not checked');$('#serviceSummary').textContent=(lang==='ar'?ar:en).setupSummary;return}const checks=[['translation_ready',t('نموذج الترجمة العربية','Arabic translation model')],['ocr_ready',t('قراءة النص الإنجليزي OCR','English OCR')],['stream_configured',t('إعدادات بث الفيديو — لم يُختبر الاتصال','Video configuration — connection not tested')]];for(const [key,label] of checks){const row=document.createElement('div'),a=document.createElement('span'),b=document.createElement('strong');row.className='capability-row';a.textContent=label;b.textContent=healthState[key]?t('متوفر','Available'):t('غير جاهز','Not ready');b.className=healthState[key]?'yes':'no';row.append(a,b);area.append(row)}$('#serverStatus').textContent=t('الخادم متصل','Server connected');$('#serviceSummary').textContent=healthState.translation_ready&&healthState.ocr_ready?t('خدمات الترجمة وقراءة الشاشة جاهزة على الخادم. جرّب لقطة من لعبتك.','Translation and OCR services are ready on the server. Try a screenshot from your game.'):t('الخادم متصل، لكن إعداد خدمات الترجمة غير مكتمل. راجع نتائج الفحص.','Server connected, but translation setup is incomplete. Review the checks.');}
function requireCapability(kind){if(!healthState){view('connect');throw Error(t('افحص اتصال الخادم أولاً. لا توجد خدمة ترجمة متصلة تلقائياً.','Test the server connection first. No translation service is connected automatically.'))}if(!healthState.translation_ready&&kind!=='stream')throw Error(t('نموذج العربية غير جاهز. شغّل مُثبّت النموذج أو python start.py.','Arabic model is not ready. Run the model installer or python start.py.'));if(kind==='ocr'&&!healthState.ocr_ready)throw Error(t('خدمة OCR غير جاهزة؛ تحقق من تثبيت Tesseract وبيانات الإنجليزية.','OCR is not ready; check Tesseract and English language data.'));if(kind==='stream'&&!healthState.stream_configured)throw Error(t('بث الفيديو غير مهيأ على الخادم. راجع خطوات Linux في README.','Video streaming is not configured. See Linux setup in README.'));}
function invalidateConnection(){healthState=null;refreshHealth();stopCapture();stopStream();leaveRoom();}$('#serverURL').addEventListener('input',invalidateConnection);$('#apiToken').addEventListener('input',invalidateConnection);
function updateCropGuide(){const region=$('#ocrRegion').value,g=$('#cropGuide');g.hidden=region==='full'||!captureStream;const bounds={bottom:[55,45],top:[0,45],center:[25,50]};if(bounds[region]){g.style.top=bounds[region][0]+'%';g.style.height=bounds[region][1]+'%'}}$('#ocrRegion').onchange=updateCropGuide;
setLang();view('platforms');
